    H=len(inp); W=len(inp[0])
    def ok(p):
        if not(0<=p[0]<H and 0<=p[1]<W): return False
        return inp[p[0]][p[1]]==8
    n,s,w,e=ok((i-1,j)),ok((i+1,j)),ok((i,j-1)),ok((i,j+1))
    v=n and s; h=w and e; d=((n and e) or (s and w)); x=(n and w) or (s and e)
    return (v,h,d,x)
